"""Embedded app icon data for runtime window/taskbar icon."""

from __future__ import annotations

from PyQt6.QtCore import QByteArray
from PyQt6.QtGui import QIcon, QPixmap

_ICON_B64 = """"""

def get_embedded_app_icon() -> QIcon:
    data = QByteArray.fromBase64(_ICON_B64.encode("ascii"))
    pixmap = QPixmap()
    if pixmap.loadFromData(data, "ICO"):
        return QIcon(pixmap)
    return QIcon()
